CREATE TABLE items (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name text NOT NULL UNIQUE,
    quantity integer NOT NULL DEFAULT 0 CHECK (quantity >= 0),
    price numeric(10, 2),
    tags text[] DEFAULT '{}'
);

CREATE INDEX items_name_idx ON items USING btree (lower(name));

-- Upsert a row.
INSERT INTO items (name, quantity, price)
VALUES ('bolt', 120, 0.25), ('nut', 4, 0.10)
ON CONFLICT (name) DO UPDATE SET quantity = items.quantity + EXCLUDED.quantity
RETURNING id;

UPDATE items SET price = price * 1.1 WHERE quantity > 100;

WITH levels AS (
    SELECT name, quantity,
           CASE WHEN quantity > 100 THEN 'bulk' ELSE 'normal' END AS level
    FROM items
)
SELECT l.name, l.level, count(*) OVER (PARTITION BY l.level) AS level_count
FROM levels AS l
WHERE l.quantity BETWEEN 0 AND 1000
ORDER BY l.name
LIMIT 10;

CREATE FUNCTION item_total(p_name text) RETURNS numeric
LANGUAGE sql STABLE
AS $$ SELECT quantity * price FROM items WHERE name = p_name $$;

BEGIN;
DELETE FROM items WHERE quantity = 0;
COMMIT;

CREATE TABLE orders (
    id bigint PRIMARY KEY,
    total numeric(10, 2) NOT NULL
);

INSERT INTO orders (id, total) VALUES (1, 10.50), (2, 99.00);

SELECT id, total
FROM orders
WHERE total > (SELECT avg(total) FROM orders);
